import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { realpathSync, statSync } from 'node:fs';
import { resolve } from 'node:path';
import { formatDuration } from './duration.mjs';

const script = resolve('duration.mjs');
const maximum = BigInt(Number.MAX_SAFE_INTEGER);
const expected = n => "'`${n / 3600n}:${String(n / 60n % 60n).padStart(2, '"'0')}:"'${String(n % 60n).padStart(2, '"'0')}"'`;
let apiChecks = 0;
for (let i = 0n; i < 10000n; i++) {
  for (const n of [i, maximum - i, (i * 6364136223846793005n + 1442695040888963407n) % (maximum + 1n)]) {
    assert.equal(formatDuration(Number(n)), expected(n));
    apiChecks++;
  }
}
assert.equal(formatDuration(-0), '"'0:00:00');
let cliChecks = 0;
function check(command, args, output) {
  const r = spawnSync(command, args, { encoding: 'utf8', cwd: '/' });
  assert.ifError(r.error);
  assert.equal(r.signal, null);
  if (output === null) {
    assert.notEqual(r.status, 0, JSON.stringify(args));
    assert.equal(r.stdout, '');
    assert.ok(r.stderr.length > 0);
  } else {
    assert.equal(r.status, 0, r.stderr);
    assert.equal(r.stdout, output);
    assert.equal(r.stderr, '');
  }
  cliChecks++;
}
const alias = script.replace(/"'^'"\\/private/, '');
assert.equal(realpathSync(script), realpathSync(alias));
assert.equal(statSync(script).mode & 0o777, 0o755);
const good = [
  [['0'], '0:00:00\\n'],
  [['--sum', '0', '59', '1'], '0:01:00\\n'],
  [['--sum', '3599', '1', '86400'], '25:00:00\\n'],
  [['--sum', '9007199254740989', '1', '1', '0'], "'`${expected(maximum)}'"\\n"'`],
  [['"'--sum', ...Array(1000).fill('1')], '0:16:40\\n'],
];
for (const [args, output] of good) {
  check(script, args, output);
  check(alias, args, output);
  check(process.execPath, [alias, ...args], output);
}
for (const token of ['1\\n', '1\\r\\n', '1\\u2028', '1\\u2029', '+0', '-0', '00', '0x10', '1e2', '１２', '1_000', '', '\\t0', '0 ']) {
  check(script, ['--sum', '60', token, '0'], null);
  check(alias, [token], null);
}
for (const args of [
  ['--sum'], ['--sum', '9007199254740991', '0', '1'],
  ['--sum', '9007199254740990', '1', '1'], ['--sum', '9007199254740993'],
  ['--sum', '0', '--sum'], ['0', '--sum', '1'],
]) check(alias, args, null);
check(process.execPath, ['--input-type=module', '-e', "'`await import(${JSON.stringify(new URL('"'./duration.mjs', import.meta.url).href)})"'`], '"'');
console.log(JSON.stringify({apiOracleComparisons: apiChecks, negativeZero: 'passed', independentCLIChecks: cliChecks, macOSAlias: alias, executableMode: '755', result: 'all passed'}, null, 2));
